import{_ as e,o as a,c as d,a2 as i}from"./chunks/framework.C-KFX0n7.js";const u=JSON.parse('{"title":"Error & Cara Menanganinya","description":"","frontmatter":{},"headers":[],"relativePath":"public/skills/teken-heula-api/references/errors.md","filePath":"public/skills/teken-heula-api/references/errors.md"}'),l={name:"public/skills/teken-heula-api/references/errors.md"};function n(s,t,o,r,g,c){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="error-cara-menanganinya" tabindex="-1">Error &amp; Cara Menanganinya <a class="header-anchor" href="#error-cara-menanganinya" aria-label="Permalink to &quot;Error &amp; Cara Menanganinya&quot;">​</a></h1><p>Semua error berformat JSON:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;The given data was invalid.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;errors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;esign.0.nip&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] } }</span></span></code></pre></div><p><code>errors</code> hanya ada di <code>422</code>; key-nya adalah path field dengan indeks array (<code>doc.file_base64</code>, <code>esign.1.signature_properties.tag</code>).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Kode</th><th style="text-align:left;">Penyebab</th><th style="text-align:left;">Retry?</th><th style="text-align:left;">Tindakan</th></tr></thead><tbody><tr><td style="text-align:left;"><code>400</code></td><td style="text-align:left;"><code>GET .../file</code> sebelum PDF selesai: <code>&quot;Dokumen masih dalam antrean proses atau file belum tersedia.&quot;</code></td><td style="text-align:left;">Ya, nanti</td><td style="text-align:left;">Lanjutkan polling status</td></tr><tr><td style="text-align:left;"><code>401</code></td><td style="text-align:left;">Token tidak dikirim, salah, atau dicabut</td><td style="text-align:left;">Tidak</td><td style="text-align:left;">Perbarui token di konfigurasi; beri alert</td></tr><tr><td style="text-align:left;"><code>403</code></td><td style="text-align:left;">Token valid tapi tidak punya permission <code>Api*:&lt;Doc&gt;</code> modul itu; atau jaringan memblokir <code>PUT</code></td><td style="text-align:left;">Tidak</td><td style="text-align:left;">Minta admin Teken Heula menambah permission; jika karena <code>PUT</code> diblokir, pakai <code>POST</code> + <code>X-HTTP-Method-Override: PUT</code></td></tr><tr><td style="text-align:left;"><code>404</code></td><td style="text-align:left;"><code>documentId</code> tidak ditemukan / bukan UUID; atau <code>&quot;File fisik dokumen tidak ditemukan di server.&quot;</code> saat download</td><td style="text-align:left;">Tidak</td><td style="text-align:left;">Cek ID yang tersimpan; kasus file fisik hilang → laporkan ke tim Teken Heula</td></tr><tr><td style="text-align:left;"><code>422</code></td><td style="text-align:left;">Validasi gagal</td><td style="text-align:left;">Tidak (dengan payload sama)</td><td style="text-align:left;">Perbaiki field sesuai <code>errors</code></td></tr><tr><td style="text-align:left;"><code>429</code></td><td style="text-align:left;">Melebihi 200 request/menit per token</td><td style="text-align:left;">Ya</td><td style="text-align:left;">Backoff (hormati header <code>Retry-After</code> jika ada)</td></tr><tr><td style="text-align:left;"><code>500</code>/<code>502</code>/<code>503</code>/timeout</td><td style="text-align:left;">Gangguan server</td><td style="text-align:left;">Ya, terbatas</td><td style="text-align:left;">Exponential backoff; untuk <code>POST</code>, cegah dokumen ganda</td></tr></tbody></table><h2 id="pesan-422-yang-umum" tabindex="-1">Pesan <code>422</code> yang umum <a class="header-anchor" href="#pesan-422-yang-umum" aria-label="Permalink to &quot;Pesan `422` yang umum&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Pesan</th><th style="text-align:left;">Penyebab</th></tr></thead><tbody><tr><td style="text-align:left;"><code>doc.file_base64</code></td><td style="text-align:left;"><code>doc.file_base64 harus berupa file PDF base64 yang valid.</code></td><td style="text-align:left;">Bukan PDF, ada prefix <code>data:</code>, terpotong, atau ada baris baru</td></tr><tr><td style="text-align:left;"><code>esign.N.signature_properties.imageBase64</code></td><td style="text-align:left;"><code>... harus berupa gambar PNG/JPG/JPEG base64 yang valid.</code></td><td style="text-align:left;">Gambar bukan PNG/JPG atau base64 rusak</td></tr><tr><td style="text-align:left;"><code>esign.N.nip</code></td><td style="text-align:left;"><code>esign.N.nip belum terdaftar sebagai pengguna e-sign dan gagal disinkronkan.</code></td><td style="text-align:left;">NIP tidak ditemukan di Sinergi (SDM UPI)</td></tr><tr><td style="text-align:left;"><code>eseal.nip</code></td><td style="text-align:left;"><code>eseal.nip belum terdaftar sebagai pengguna e-seal dan gagal disinkronkan dari Sinergi.</code></td><td style="text-align:left;">(Language Cert) NIP bukan pemilik e-seal</td></tr><tr><td style="text-align:left;"><code>esign.N.nip</code></td><td style="text-align:left;"><code>NIP duplikat pada data esign.</code></td><td style="text-align:left;">NIP sama muncul dua kali</td></tr><tr><td style="text-align:left;"><code>esign.N.signature_properties.tag</code></td><td style="text-align:left;"><code>Tag duplikat pada data esign.</code></td><td style="text-align:left;">Dua penandatangan memakai tag sama</td></tr><tr><td style="text-align:left;"><code>esign.N.order</code></td><td style="text-align:left;"><code>Urutan tanda tangan tidak boleh duplikat.</code></td><td style="text-align:left;"><code>order</code> sama</td></tr><tr><td style="text-align:left;"><code>doc.mandala_doc_id</code></td><td style="text-align:left;"><code>Mandala Doc ID sudah digunakan.</code></td><td style="text-align:left;">(Mandala) ID referensi sudah dipakai dokumen lain</td></tr><tr><td style="text-align:left;"><code>document_id</code></td><td style="text-align:left;"><code>document_id yang diberikan tidak ditemukan.</code></td><td style="text-align:left;">PUT ke UUID yang tidak ada</td></tr><tr><td style="text-align:left;"><code>doc</code></td><td style="text-align:left;"><code>Dokumen sedang dalam antrean proses e-seal/e-sign dan tidak dapat diubah ...</code></td><td style="text-align:left;">(Language Cert) ganti file/eseal/esign saat <code>in_queue</code></td></tr><tr><td style="text-align:left;"><code>doc</code></td><td style="text-align:left;"><code>Minimal satu field (doc, eseal, atau esign) harus diisi untuk update.</code></td><td style="text-align:left;">(Language Cert) PUT dengan body kosong</td></tr></tbody></table><h2 id="pdf-hasil-tidak-bisa-dibuka" tabindex="-1">PDF hasil tidak bisa dibuka <a class="header-anchor" href="#pdf-hasil-tidak-bisa-dibuka" aria-label="Permalink to &quot;PDF hasil tidak bisa dibuka&quot;">​</a></h2><p>Hampir selalu karena <code>file_base64</code> saat POST/PUT tidak valid (terpotong, ada prefix <code>data:...;base64,</code>, atau di-encode dua kali). Simpan response download sebagai <strong>binary</strong>, bukan string teks/JSON.</p>',9)])])}const y=e(l,[["render",n]]);export{u as __pageData,y as default};
